mapper.select:
SELECT COUNT(*)
FROM visit_log
WHERE created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COUNT(DISTINCT visitor_id)
FROM visit_log
WHERE created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COUNT(DISTINCT COALESCE(NULLIF(session_id, ''), visitor_id))
FROM visit_log
WHERE created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT
    path,
    COUNT(*) AS count
FROM visit_log
WHERE created_at >= #{startTime}
  AND created_at < #{endTime}
GROUP BY path
ORDER BY count DESC, path ASC
LIMIT #{limit}

SELECT DATE_FORMAT(created_at, '%Y-%m-%d') AS date, COUNT(DISTINCT visitor_id) AS uv, COUNT(*) AS pv, COUNT(DISTINCT COALESCE(NULLIF(session_id, ''), visitor_id)) AS sessions FROM visit_log
created_at >= #{startTime}
AND created_at < #{endTime}
GROUP BY DATE_FORMAT(created_at, '%Y-%m-%d') ORDER BY date ASC
